const float RADIUS = 0.5;
const float MOVEMENT_SCALE = -4.0;
const float TRAIL_ITER = 20.0;
const float TRAIL_DISTANCE = 0.2;

// https://iquilezles.org/articles/distfunctions2d/
float sdCircle( vec2 p, float r )
{
    return length(p) - r;
}

float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv -= .5;
    uv.x *= iResolution.x / iResolution.y;

    // Control movement scale with mouse y position
    float m = MOVEMENT_SCALE * iMouse.y / iResolution.y;

    // Control radius with mouse x position
    float r = RADIUS * iMouse.x / iResolution.x;


    // Time varying pixel color
    vec3 gradCol = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // first joint is in the center
    vec2 joint1 = vec2(0.0); 
    vec2 joint2 = vec2(cos(iTime), sin(iTime)) * r;
    vec2 joint3 = joint2 + vec2(cos(iTime * m), sin(iTime * m)) * r * 0.5;

    float seg1 = sdSegment(uv, joint1, joint2);
    float seg2 = sdSegment(uv, joint2, joint3);

    vec3 col = vec3(0.);
    col = mix(gradCol, col, smoothstep(0.0, 0.01, seg1));
    col = mix(gradCol, col, smoothstep(0.0, 0.01, seg2));


    // Render circles on mouse down
    if (iMouse.z > 0.0) {
        float circle1 = sdCircle(uv, r);
        float circle2 = sdCircle((joint2 - uv) * 2.0, r);
        col = mix(gradCol, col, smoothstep(circle1, 0.0, 0.01));
        col = mix(gradCol, col, smoothstep(circle2, 0.0, 0.01));
    }


    for (float i = 0.0; i < TRAIL_ITER; i += TRAIL_DISTANCE) {
        // Recalculate joints 2 and 3, going back in time
        float t = iTime - i;
        vec2 joint2 = vec2(cos(t), sin(t)) * r;
        vec2 joint3 = joint2 + vec2(cos(t * m), sin(t * m)) * r * 0.5;

        float trailDot = sdCircle((joint3 - uv) * 40.0, r);

        col = mix(gradCol * (TRAIL_ITER - i) / TRAIL_ITER, col, smoothstep(0.0, 0.01, trailDot));

    }


    fragColor = vec4(col,1.0);
}
